import {
  colors,
  fonts,
  MIN_TOUCH_TARGET,
  membership,
  motion,
  radius,
  shadows,
  sizes,
  space,
  type,
  type ColorTokens,
} from "./tokens";

/**
 * Serialises tokens.ts into the design-system spec format (`design-system/tokens.json`).
 * Pure: no Node/DOM imports, so native apps and the docs pipeline can share it.
 * The spec file is GENERATED by `npm run tokens` — never edit it by hand.
 */

const kebab = (s: string) => s.replace(/[A-Z]/g, (m) => `-${m.toLowerCase()}`).replace(/([a-z])(\d)/g, "$1-$2");

const COLOR_USAGE: Record<keyof ColorTokens, string> = {
  paper: "App background (iOS grouped background). Dark #050506 is the default appearance.",
  surface: "Cards, list groups, sidebar.",
  elevated: "Inputs, secondary buttons, chips, segmented controls, empty states, hover/pressed rows.",
  ink: "Primary text on paper, surface and elevated (AA in both themes).",
  inkMuted: "Secondary text: descriptions, list values, ledes.",
  inkSubtle:
    "Tertiary text: group labels, footnotes, placeholders, inactive tabs. Still ≥ 4.5:1 on paper, surface and elevated.",
  line: "Hairline separators and card rings. Decorative — never a control boundary.",
  lineStrong:
    "Stronger decorative lines (chip hover ring, progress track). Below 3:1 — never marks a control boundary or state.",
  inputBorder:
    "Control boundary: field borders, switch off-track, unmet checklist rings, upcoming progress steps. ≥ 3:1 on paper, surface and elevated.",
  primary: "Primary button fill: platinum in dark, near-black in light.",
  primaryForeground: "Label on primary.",
  gold: "Champagne gold: focus rings, current progress, links and inline actions, active tab, wordmark dot, tier accents and Icon status. Never primary buttons, large fills, body text, financial figures or warning/danger meaning. Legacy alias: brand.",
  goldSoft: "Ground behind gold text (brand badge, selection highlight).",
  success: "Verified / connected / done. Also the switch on-track.",
  successSoft: "Ground for success alerts and badges.",
  warning: "Needs attention.",
  warningSoft: "Ground for warning alerts and badges.",
  danger: "Errors, invalid fields, destructive actions.",
  dangerSoft: "Ground for danger alerts, badges and the destructive button.",
  info: "Neutral information and disclosures; derived-signal badges.",
  infoSoft: "Ground for info alerts and badges.",
  bar: "Translucent top bar, tab bar and sticky form footer, always with the bar-blur utility.",
  thumb: "Switch thumb (white in both themes).",
};

const MEMBERSHIP_USAGE: Record<keyof typeof membership, string> = {
  base: "Membership card body (same in both themes).",
  ink: "Text on the membership card; secondary lines use it at 50–80% opacity.",
  accent: "Tier label, ring and wordmark full stop on the membership card.",
  sheen: "The card's single soft corner highlight.",
  edge: "Inner hairline ring of the membership card.",
  highlight: "Top-edge light catch of the membership card.",
};

const TYPE_USAGE: Record<keyof typeof type, string> = {
  largeTitle: "PageHeading (iOS Large Title) on every page.",
  title1: "MetricBlock values.",
  title2: "SectionHeading; tile titles on Access.",
  title3: "Card and tile titles on landing/dashboard.",
  headline: "Emphasised body (CardTitle, ConsentText title).",
  body: "Default text, list labels, field values (never below 16px in fields).",
  callout: "Reserved.",
  subhead: "Descriptions, ledes in cards, small buttons, labels.",
  footnote: "Group labels, field help, errors, list details, footers.",
  caption: "Compliance note, consent version.",
  caption2: "Tab bar labels; membership-card labels.",
};

const RADIUS_USAGE: Record<keyof typeof radius, string> = {
  sm: "Sidebar rows.",
  md: "Skeletons.",
  control: "Buttons (md), text fields, selects, alerts, choice rows.",
  lg: "List groups, empty states, large buttons.",
  card: "Cards and tiles.",
  xl: "Membership card.",
  pill: "Chips, badges, small and icon buttons, switches, progress bars.",
};

const SIZE_USAGE: Record<keyof typeof sizes, string> = {
  buttonSm: "Small (pill) button height — visual; isolated small buttons need a 44px hit area.",
  control: "Default button, text field and select height.",
  controlLg: "Large primary button height.",
  row: "ListRow minimum height.",
  choiceRow: "RadioRow, CheckboxRow, SwitchRow and tab bar item minimum height.",
  chip: "CheckboxChip minimum height (visual).",
  segment: "SegmentedControl segment minimum height (visual).",
  switchWidth: "Switch track width.",
  switchHeight: "Switch track height.",
  switchThumb: "Switch thumb diameter.",
  indicator: "Radio/checkbox indicator.",
  topBar: "Top bar content height (plus safe area).",
  tabBar: "Tab bar content height (plus home indicator).",
  sidebar: "Desktop sidebar width.",
  membershipCard: "Membership card max width (ID-1 ratio 1.586).",
};

function styleOf(name: keyof typeof type, usage: string) {
  const t = type[name];
  return {
    name: kebab(name),
    fontSize: `${t.size}px`,
    lineHeight: `${t.line}px`,
    fontWeight: t.weight,
    letterSpacing: `${t.tracking}px`,
    usage,
  };
}

export function renderDesignSystemTokens() {
  const colorNames = Object.keys(colors.dark) as (keyof ColorTokens)[];
  return {
    name: "CreatorCo",
    version: 2,
    meta: {
      source: "generated",
      from: "src/design/tokens.ts",
      generator: "src/design/scripts/generate-json.ts (npm run tokens)",
      note: "GENERATED — do not edit. Change src/design/tokens.ts and run `npm run tokens`.",
    },
    color: {
      themes: [
        { id: "dark", name: "Dark (default)" },
        { id: "light", name: "Light" },
      ],
      tokens: [
        ...colorNames.map((k) => ({
          name: kebab(k),
          value: { dark: colors.dark[k], light: colors.light[k] },
          usage: COLOR_USAGE[k],
        })),
        ...(Object.keys(membership) as (keyof typeof membership)[]).map((k) => ({
          name: `membership-${kebab(k)}`,
          value: membership[k],
          usage: MEMBERSHIP_USAGE[k],
        })),
      ],
    },
    type: {
      fonts: [
        { family: "Inter Variable", file: "fonts/inter-latin-wght-normal.woff2", weight: "100 900", style: "normal" },
        {
          family: "Newsreader Variable",
          file: "fonts/newsreader-latin-wght-normal.woff2",
          weight: "200 800",
          style: "normal",
        },
      ],
      families: { sans: fonts.sans, serif: fonts.serif, mono: fonts.mono },
      groups: [
        {
          name: "Interface — SF Pro (Inter fallback)",
          family: "sans",
          styles: (Object.keys(type) as (keyof typeof type)[]).map((k) => styleOf(k, TYPE_USAGE[k])),
        },
        {
          name: "Brand moments — Newsreader",
          family: "serif",
          styles: [
            {
              name: "wordmark",
              fontSize: "22px",
              lineHeight: 1,
              fontWeight: 400,
              letterSpacing: "-0.025em",
              sample: "CreatorCo",
              usage: "Wordmark (19px in bars). Placeholder name — swap the Wordmark component only.",
            },
          ],
        },
      ],
    },
    spacing: {
      tokens: Object.entries(space).map(([k, v]) => ({
        name: `space-${k}`,
        value: `${v}px`,
        usage: "4-pt spacing scale (Tailwind steps).",
      })),
    },
    radius: {
      tokens: (Object.keys(radius) as (keyof typeof radius)[]).map((k) => ({
        name: `radius-${kebab(k)}`,
        value: `${radius[k]}px`,
        usage: RADIUS_USAGE[k],
      })),
    },
    shadow: {
      note: "Only three elevations exist. Everything else uses borders and surface contrast.",
      tokens: [
        {
          name: "shadow-membership-card",
          value: shadows.membershipCard,
          usage: "Membership card only — the one place for depth.",
        },
        { name: "shadow-thumb", value: shadows.thumb, usage: "Switch thumb (functional)." },
        {
          name: "shadow-overlay",
          value: { dark: shadows.overlay.dark, light: shadows.overlay.light },
          usage: "Floating surfaces: sheets, menus, dialogs, toasts.",
        },
      ],
    },
    size: {
      tokens: [
        ...(Object.keys(sizes) as (keyof typeof sizes)[]).map((k) => ({
          name: `size-${kebab(k)}`,
          value: `${sizes[k]}px`,
          usage: SIZE_USAGE[k],
        })),
        {
          name: "touch-target",
          value: `${MIN_TOUCH_TARGET}px`,
          usage: "MIN_TOUCH_TARGET — minimum hit area for any interactive element.",
        },
      ],
    },
    timing: {
      tokens: [
        { name: "motion-fast", value: `${motion.fastMs}ms`, usage: "Press feedback, colour changes." },
        { name: "motion-base", value: `${motion.baseMs}ms`, usage: "Switches, sheets, state changes." },
        { name: "motion-slow", value: `${motion.slowMs}ms`, usage: "Progress meter fill." },
        { name: "motion-spring", value: motion.spring, usage: "Default easing (iOS-like spring curve)." },
        { name: "motion-press-scale", value: String(motion.pressScale), usage: "Button press scale." },
        { name: "motion-press-opacity", value: String(motion.pressOpacity), usage: "Button press opacity." },
        { name: "motion-bar-blur", value: `${motion.barBlurPx}px`, usage: "Backdrop blur for translucent bars only." },
      ],
    },
  };
}
